import{_ as s,C as r,o as a,c as i,j as t,a as n,E as l,a6 as d}from"./chunks/framework.CCKCzdWs.js";const k=JSON.parse(`{"title":"Runs started in a terminal","description":"A Playwright run you start in a terminal, in a folder of your editor's workspace, follows that editor window: it stops at its breakpoints and takes its controls, as a run Piwi started does.","frontmatter":{"title":"Runs started in a terminal","description":"A Playwright run you start in a terminal, in a folder of your editor's workspace, follows that editor window: it stops at its breakpoints and takes its controls, as a run Piwi started does.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/terminal-runs.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/terminal-runs.html"}],["meta",{"property":"og:title","content":"Runs started in a terminal | Piwi Dashboard"}],["meta",{"property":"og:description","content":"A Playwright run you start in a terminal, in a folder of your editor's workspace, follows that editor window: it stops at its breakpoints and takes its controls, as a run Piwi started does."}]]},"headers":[],"relativePath":"features/terminal-runs.md","filePath":"features/terminal-runs.md","lastUpdated":1793207199000}`),h={name:"features/terminal-runs.md"};function u(c,e,w,p,f,m){const o=r("Needs");return a(),i("div",null,[e[0]||(e[0]=t("h1",{id:"runs-started-in-a-terminal",tabindex:"-1"},[n("Runs started in a terminal "),t("a",{class:"header-anchor",href:"#runs-started-in-a-terminal","aria-label":'Permalink to "Runs started in a terminal"'},"​")],-1)),l(o,{fixtures:""}),e[1]||(e[1]=d('<p>A run you start yourself, <code>npx playwright test</code> in a terminal, follows the VS Code or JetBrains window whose workspace holds it, with a reporter and an editor extension newer than 0.62.0. It stops at the editor&#39;s breakpoints, shows in the editor and in Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a> as a run in a terminal, and takes the same controls (<a href="./editor-run-control.html">Pause and step from the editor</a>) but <strong>Stop</strong>: its process is the terminal&#39;s. It says so as it starts:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Piwi Dashboard] Following this run in Visual Studio Code (pid 41230), whose breakpoints stop it: PIWI_EDITOR=off runs it alone.</span></span></code></pre></div><p>It runs as its config says, headless by default, so the editor shows a stop as <a href="./editor-run-control.html#a-headless-run">a headless run&#39;s</a>: an image of its page, which Piwi Picker can watch live.</p><h2 id="which-editor" tabindex="-1">Which editor <a class="header-anchor" href="#which-editor" aria-label="Permalink to &quot;Which editor&quot;">​</a></h2><p>Each editor window&#39;s Piwi service writes a file in <code>~/.piwi/editors</code> (<code>PIWI_EDITORS_DIR</code> names another folder) with its workspace folders and where its runs connect. The run follows the window one of whose folders holds its Playwright config&#39;s folder or its working directory, links resolved: the most specific folder wins, then the window that started last. A window of another machine, another user&#39;s, or one whose process ended is never followed, nor is a file written before the machine last started, any file of a folder another user can open, or (but on Windows) a window whose runs would connect through a folder another user can open.</p><h2 id="when-it-follows-one" tabindex="-1">When it follows one <a class="header-anchor" href="#when-it-follows-one" aria-label="Permalink to &quot;When it follows one&quot;">​</a></h2><ul><li><strong>Only a run whose output goes to a terminal.</strong> One whose output goes to a file or a pipe runs alone, unless it sets <code>PIWI_EDITOR=on</code>.</li><li><strong>Never</strong> under CI, with Playwright&#39;s own debugger (<code>--debug</code>, <code>PWDEBUG=1</code>) or UI mode, when the run names its own <code>PIWI_RUN_CHANNEL</code>, or when the desktop app or another launcher started it.</li><li><strong><code>PIWI_EDITOR=off</code></strong> runs it alone.</li></ul><h2 id="what-it-takes-from-the-editor" tabindex="-1">What it takes from the editor <a class="header-anchor" href="#what-it-takes-from-the-editor" aria-label="Permalink to &quot;What it takes from the editor&quot;">​</a></h2><ul><li><strong>The breakpoints.</strong> It starts with the editor&#39;s breakpoints as they are, then takes them as you change them, while <code>piwi.breakpoints</code> (<strong>Pause the runs Piwi starts at the editor&#39;s breakpoints</strong> in a JetBrains IDE) is on. Without any, it runs as it would, and <strong>Pause</strong> stops it.</li><li><strong>The controls</strong>: Pause, Resume, Step, Run to cursor, Finish and <a href="./end-the-test.html">End the test</a>, and the code a stop makes, Assert a region and Mock a request, written in the editor (<a href="./editor-stop-code.html">Code from a pause</a>).</li><li><strong>Failures.</strong> A failure is held only while the Runs window follows the editor&#39;s runs as the worker starts: nobody may be there to answer it otherwise, and it goes on, as without Piwi.</li></ul><p>When the editor closes, or its service stops, the connection closes, and a stop with no pause bar goes on. The token of the editor&#39;s connection reaches the run&#39;s workers alone, out of the tests&#39; environment while they run, as for a run the editor starts.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>No Pick, Record or Assert in the test&#39;s window.</strong> They need the pairing a run Piwi starts carries: start the test from the editor to use them. Pick on the image names the locator, for you to copy, without writing it.</li><li><strong>No Stop.</strong> End the run in its terminal.</li><li><strong>Piwi&#39;s reporter in the config.</strong> The run looks for an editor as the reporter starts (<code>wrapConfig</code> adds it): with the capture fixtures alone, it runs alone.</li><li><strong>Your machine.</strong> A run in a dev container or over SSH follows an editor whose service runs there too.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the controls, and the paused line.</li><li><a href="./editor-breakpoints.html">Breakpoints in the browser</a>: the breakpoints a run takes.</li><li><a href="./editor-runs.html">Runs from the editor</a>: the runs Piwi starts.</li><li><a href="./runs-window.html">Runs window</a>: the same runs, in Piwi Picker.</li></ul>',14))])}const P=s(h,[["render",u]]);export{k as __pageData,P as default};
